const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5
pres.author = 'WorkspaceX';
pres.title = '团队协作：打造高效能团队';

// Color palette
const C = {
  primary: '1B3A5C',    // deep navy
  accent: '2E86DE',     // bright blue
  light: 'EBF5FB',      // very light blue bg
  white: 'FFFFFF',
  dark: '2C3E50',       // near-black text
  gray: '7F8C8D',
  orange: 'E67E22',
  green: '27AE60',
  red: 'E74C3C',
};

const FONT = '微软雅黑';

// Helper: add consistent footer
function addFooter(slide, pageNum) {
  slide.addText(`${pageNum} / 5`, {
    x: 12.0, y: 7.0, w: 1.0, h: 0.35,
    fontSize: 10, color: C.gray, fontFace: FONT, align: 'right'
  });
  // accent line at bottom
  slide.addShape(pres.ShapeType.rect, {
    x: 0, y: 7.25, w: 13.33, h: 0.25, fill: { color: C.accent }
  });
}

// ===================== SLIDE 1: Title =====================
{
  const s = pres.addSlide();
  // Background
  s.addShape(pres.ShapeType.rect, {
    x: 0, y: 0, w: 13.33, h: 7.5, fill: { color: C.primary }
  });
  // Decorative circle
  s.addShape(pres.ShapeType.ellipse, {
    x: 9.5, y: -1.5, w: 5.5, h: 5.5, fill: { color: C.accent }, transparency: 70
  });
  s.addShape(pres.ShapeType.ellipse, {
    x: -1.5, y: 5.0, w: 4.0, h: 4.0, fill: { color: C.accent }, transparency: 80
  });

  s.addText('团队协作', {
    x: 1.0, y: 2.0, w: 11.0, h: 1.5,
    fontSize: 54, bold: true, color: C.white, fontFace: FONT, align: 'center'
  });
  s.addText('打造高效能团队的五大核心要素', {
    x: 1.0, y: 3.6, w: 11.0, h: 0.8,
    fontSize: 24, color: C.light, fontFace: FONT, align: 'center'
  });
  // Divider line
  s.addShape(pres.ShapeType.rect, {
    x: 5.0, y: 4.6, w: 3.33, h: 0.06, fill: { color: C.accent }
  });
  s.addText('2024 · 内部培训材料', {
    x: 1.0, y: 5.0, w: 11.0, h: 0.6,
    fontSize: 16, color: C.gray, fontFace: FONT, align: 'center'
  });
}

// ===================== SLIDE 2: Why Team Collaboration Matters =====================
{
  const s = pres.addSlide();
  s.addShape(pres.ShapeType.rect, {
    x: 0, y: 0, w: 13.33, h: 7.5, fill: { color: C.white }
  });
  // Header bar
  s.addShape(pres.ShapeType.rect, {
    x: 0, y: 0, w: 13.33, h: 1.2, fill: { color: C.primary }
  });
  s.addText('为什么团队协作至关重要？', {
    x: 0.8, y: 0.15, w: 11.0, h: 0.9,
    fontSize: 32, bold: true, color: C.white, fontFace: FONT
  });

  // Three cards
  const cards = [
    { icon: '🚀', title: '提升效率', desc: '协同分工减少重复劳动，\n项目交付速度提升 40%+', color: C.accent },
    { icon: '💡', title: '激发创新', desc: '多元视角碰撞产生创意，\n跨职能团队创新率高出 35%', color: C.orange },
    { icon: '🤝', title: '增强韧性', desc: '互相补位降低单点风险，\n团队抗压与适应能力更强', color: C.green },
  ];

  cards.forEach((c, i) => {
    const cx = 0.8 + i * 4.1;
    // Card background
    s.addShape(pres.ShapeType.roundRect, {
      x: cx, y: 1.8, w: 3.7, h: 4.5, rectRadius: 0.15,
      fill: { color: C.light }, shadow: { type: 'outer', blur: 6, offset: 2, color: 'CCCCCC', opacity: 0.3 }
    });
    // Icon circle
    s.addShape(pres.ShapeType.ellipse, {
      x: cx + 1.15, y: 2.2, w: 1.4, h: 1.4, fill: { color: c.color }
    });
    s.addText(c.icon, {
      x: cx + 1.15, y: 2.25, w: 1.4, h: 1.3,
      fontSize: 36, align: 'center', valign: 'middle', fontFace: FONT
    });
    // Title
    s.addText(c.title, {
      x: cx + 0.2, y: 3.85, w: 3.3, h: 0.6,
      fontSize: 22, bold: true, color: C.dark, fontFace: FONT, align: 'center'
    });
    // Desc
    s.addText(c.desc, {
      x: cx + 0.2, y: 4.5, w: 3.3, h: 1.5,
      fontSize: 14, color: C.dark, fontFace: FONT, align: 'center', lineSpacingMultiple: 1.4
    });
  });

  addFooter(s, 2);
}

// ===================== SLIDE 3: Five Core Elements =====================
